"""Golden-file snapshots of the generated files for the sonarr example, plus the structural rules of the renderer."""

from __future__ import annotations

import os
from pathlib import Path

import pytest

from builder.manifest import Settings, build_context, read_manifest_data
from builder.render import ALL_FILES, OUT_DIR, REPO_FILES, render_all

from .conftest import EXAMPLES, GOLDEN, SETTINGS

GOLDEN_FILES = {"README.md": "README.md", f"{OUT_DIR}/docs.md": "docs.md", "AGENTS.md": "AGENTS.md"}


def _sonarr() -> dict[str, object]:
    data: dict[str, object] = read_manifest_data(EXAMPLES / "sonarr" / "image.yml")
    return data


@pytest.mark.parametrize("rendered,golden", sorted(GOLDEN_FILES.items()))
def test_sonarr_matches_golden(rendered: str, golden: str) -> None:
    files = render_all(_sonarr(), SETTINGS)
    path = GOLDEN / "sonarr" / golden
    if os.environ.get("UPDATE_GOLDEN"):
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(files[rendered], encoding="utf-8")
    assert files[rendered] == path.read_text(encoding="utf-8"), (
        f"{rendered} drifted from {path}; UPDATE_GOLDEN=1 to accept"
    )


def test_every_generated_file_is_rendered() -> None:
    files = render_all(_sonarr(), SETTINGS)
    assert tuple(files) == ALL_FILES
    assert all(content.endswith("\n") and not content.endswith("\n\n") for content in files.values())


@pytest.mark.parametrize("path", sorted(EXAMPLES.glob("*/image.yml")), ids=lambda p: p.parent.name)
def test_all_examples_render(path: Path) -> None:
    files = render_all(read_manifest_data(path), SETTINGS)
    assert "## Usage" in files["README.md"]
    assert "## Versions" in files["README.md"]


def test_readme_has_the_expected_sections_in_order() -> None:
    readme = render_all(_sonarr(), SETTINGS)["README.md"]
    headings = [line for line in readme.splitlines() if line.startswith("## ")]
    assert headings == [
        "## Supported Architectures",
        "## Version Tags",
        "## Application Setup",
        "## Read-Only Operation",
        "## Non-Root Operation",
        "## Usage",
        "## Parameters",
        "## Environment variables from files (Docker secrets)",
        "## Umask for running applications",
        "## User / Group Identifiers",
        "## Docker Mods",
        "## Support Info",
        "## Updating Info",
        "## Building locally",
        "## Versions",
    ]
    for banned in ("jenkins", "gitlab", "quay.io", "scarf", "hub.docker.com"):
        assert banned not in readme.lower(), banned


def test_badges_point_at_the_new_world() -> None:
    readme = render_all(_sonarr(), SETTINGS)["README.md"]
    assert "https://ci.thelamer.duckdns.org:8443/badge/sonarr/latest.svg" in readme
    assert "https://linuxserver-playground.github.io/hub/mods/?image=sonarr" in readme
    assert "https://github.com/linuxserver-playground/docker-sonarr/releases" in readme
    assert "ghcr.io/linuxserver-playground/sonarr:latest" in readme


def test_control_url_is_configurable() -> None:
    settings = Settings.from_env({"BUILDER_CONTROL_URL": "https://control.example"})
    readme = render_all(_sonarr(), settings)["README.md"]
    assert "https://control.example/badge/sonarr/latest.svg" in readme


def test_docs_page_front_matter() -> None:
    docs = render_all(_sonarr(), SETTINGS)[f"{OUT_DIR}/docs.md"]
    head = docs.split("---\n")[1]
    assert "title: sonarr" in head
    assert "    - Media Management" in head
    assert head.strip().endswith('becomes available."')
    assert '??? tip "Well planned paths"' in docs
    assert "!!! info" in docs
    assert "> [!NOTE]" not in docs


def test_readme_uses_github_alerts() -> None:
    readme = render_all(_sonarr(), SETTINGS)["README.md"]
    assert "> [!NOTE]\n> Unless a parameter is flagged" in readme
    assert "!!! info" not in readme


def test_workflow_is_the_fixed_text() -> None:
    workflow = render_all(_sonarr(), SETTINGS)[".github/workflows/build.yml"]
    assert workflow.startswith("# Generated by builder from image.yml. Do not edit; the shared workflow rewrites")
    assert "uses: linuxserver-playground/workflows/.github/workflows/image-build.yml@v1" in workflow
    assert "reason: ${{ github.event.inputs.reason || github.event.client_payload.reason || 'push' }}" in workflow
    assert "group: build-${{ github.ref }}" in workflow
    # The shared workflow asks for write tokens; the caller must grant them or GitHub refuses to start.
    assert "      packages: write\n" in workflow
    assert "repository_dispatch:" in workflow
    # Closed pull requests reach the shared workflow too: its cleanup job deletes the untrusted-pr images.
    assert "  pull_request:\n    types: [opened, synchronize, reopened, closed]\n" in workflow


def test_agents_md_context() -> None:
    data = _sonarr()
    ctx = build_context(data, SETTINGS)
    assert ctx["live_branches"] == ["master", "develop"]
    assert ctx["version_arg"] == "SONARR_VERSION"
    assert ctx["test_ports"] == ["8989"]
    agents = render_all(data, SETTINGS)["AGENTS.md"]
    assert "# AGENTS.md - docker-sonarr" in agents
    assert "Live branches: master, develop." in agents
    assert "-p 8989:8989 sonarr:test" in agents
    assert "CI passes `SONARR_VERSION`" in agents
    assert SETTINGS.schema_url in agents


def test_custom_readme_replaces_the_body() -> None:
    data = _sonarr()
    data["docs"]["custom_readme"] = "# Internal tool\n\nHand written."  # type: ignore[index]
    files = render_all(data, SETTINGS)
    assert files["README.md"].endswith("# Internal tool\n\nHand written.\n")
    assert "## Usage" not in files["README.md"]
    assert "title: sonarr" in files[f"{OUT_DIR}/docs.md"]


def test_optional_sections_follow_the_manifest() -> None:
    data = read_manifest_data(EXAMPLES / "swag" / "image.yml")
    readme = render_all(data, SETTINGS)["README.md"]
    assert "## Version Tags" not in readme
    assert "### Portainer notice" in readme
    assert "| `--cap-add=NET_ADMIN` |" in readme
    assert "## Non-Root Operation" not in readme
    assert "### Caveats" in readme
    assert "&include_prereleases" not in readme


def test_repo_files_are_the_committed_ones() -> None:
    assert REPO_FILES == ("README.md", "AGENTS.md", "LICENSE", ".github/workflows/build.yml")
